// One export standard for the whole app.
// CSV: UTF-8 with a BOM (Excel shows Arabic and other non-ASCII names), CRLF line ends, every cell
//      quoted, formula injection neutralised, the same columns whether or not there are rows, and
//      raw values (numbers as numbers, ISO dates) rather than screen formatting.
// PDF: organisation name (and logo when one is set), title, the filters used, "Generated by … on …",
//      the table with its header repeated on every page, an optional totals row, "Page x of y".
import { currentReportUser, orgLogoUrl, orgName } from '../lib/branding';
import { todayYmd } from './date';

/**
 * Neutralise spreadsheet formula injection: a text cell that starts with = + - @ (or tab / CR)
 * is prefixed with an apostrophe so Excel/Sheets treat it as text. Real numbers and plain numeric
 * strings (e.g. "-12.500") are left untouched.
 */
export function csvSafeCell(val: unknown): string {
  const str = typeof val === 'object' ? JSON.stringify(val) : String(val);
  if (typeof val === 'number') return str;
  if (/^[-+]?\d+(\.\d+)?$/.test(str)) return str;
  return /^[=+\-@\t\r]/.test(str) ? `'${str}` : str;
}

const BOM = '﻿';
const quote = (v: unknown) => (v === null || v === undefined ? '""' : `"${csvSafeCell(v).replace(/"/g, '""')}"`);

/** CSV text (with BOM) from a header and rows of raw values. */
export function toCsv(header: string[], rows: unknown[][]): string {
  return BOM + [header, ...rows].map(r => r.map(quote).join(',')).join('\r\n') + '\r\n';
}

/** Save a Blob as a file. */
export function downloadBlob(fileName: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** Download a CSV named `<filename>_<today>.csv` (pass `dated: false` for a fixed name, e.g. a template). */
export function downloadCsv(filename: string, header: string[], rows: unknown[][], opts: { dated?: boolean } = {}): void {
  const name = opts.dated === false ? `${filename}.csv` : `${filename}_${todayYmd()}.csv`;
  downloadBlob(name, new Blob([toCsv(header, rows)], { type: 'text/csv;charset=utf-8' }));
}

/**
 * CSV of objects. With `headers` the columns are exactly those, in that order (stable even when
 * there are no rows); without, the keys of the first row.
 */
export function exportToCSV<T extends Record<string, any>>(
  filename: string,
  data: T[],
  headers?: { key: keyof T; label: string }[],
): void {
  const cols = headers?.length ? headers : Object.keys(data[0] ?? {}).map(k => ({ key: k as keyof T, label: k }));
  downloadCsv(filename, cols.map(c => c.label), (data ?? []).map(item => cols.map(c => item[c.key])));
}

/** JSON download. */
export function exportToJSON(filename: string, data: any): void {
  downloadBlob(`${filename}_${todayYmd()}.json`, new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }));
}

/** Print window / trigger browser print for invoices & reports. */
export function printElement(_elementId?: string): void {
  window.print();
}

/** One cell as plain text for PDF / preview output. */
export function cellToText(val: unknown): string {
  if (val === null || val === undefined) return '';
  if (typeof val === 'number') return Number.isInteger(val) ? String(val) : val.toFixed(3);
  if (typeof val === 'boolean') return val ? 'Yes' : 'No';
  if (typeof val === 'object') return '';
  return String(val);
}

export interface PdfOptions {
  /** Free text under the title (kept for existing callers). */
  subtitle?: string;
  /** The filters the data was produced with, e.g. [['Office', 'Head Office'], ['Period', 'Jan 2026']]. */
  filters?: [string, string][];
  /** Column indexes to right-align (numbers). */
  rightAlign?: number[];
  /** A totals row printed once, after the last row. */
  totals?: string[];
}

/** The lines printed above every exported table (exported for tests and the preview). */
export function pdfHeaderLines(opts: PdfOptions = {}, now = new Date()): string[] {
  const by = currentReportUser();
  const lines = [`Generated ${by ? `by ${by} ` : ''}on ${now.toLocaleString()}`];
  const f = (opts.filters ?? []).filter(([, v]) => v !== '' && v != null).map(([k, v]) => `${k}: ${v}`);
  if (f.length) lines.unshift(`Filters: ${f.join('  ·  ')}`);
  if (opts.subtitle) lines.unshift(opts.subtitle);
  return lines;
}

async function logoDataUrl(): Promise<{ data: string; format: string } | null> {
  const url = orgLogoUrl();
  if (!url) return null;
  try {
    const blob = await (await fetch(url)).blob();
    const format = blob.type.includes('png') ? 'PNG' : blob.type.includes('webp') ? 'WEBP' : 'JPEG';
    const data = await new Promise<string>((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result)); r.onerror = rej; r.readAsDataURL(blob); });
    return { data, format };
  } catch { return null; }   // a missing logo never blocks the export
}

/**
 * Real PDF download (no print dialog) in the standard layout. jsPDF is loaded on demand so it
 * does not weigh down the first page load. An empty table still produces the document (header
 * row and "No rows" line), so the file always says what was asked for.
 */
export async function exportToPDF(
  filename: string,
  title: string,
  columns: string[],
  rows: string[][],
  opts: PdfOptions = {},
): Promise<void> {
  const [{ jsPDF }, autoTableMod, logo] = await Promise.all([import('jspdf'), import('jspdf-autotable'), logoDataUrl()]);
  const autoTable = autoTableMod.default;
  const doc = new jsPDF({ orientation: columns.length > 6 ? 'landscape' : 'portrait', unit: 'pt', format: 'a4' });
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const left = 40;

  let x = left;
  if (logo) { try { doc.addImage(logo.data, logo.format, left, 24, 28, 28); x = left + 36; } catch { /* unsupported image */ } }
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(8, 99, 67);
  doc.text(orgName(), x, 32);
  doc.setTextColor(0);
  doc.setFontSize(15);
  doc.text(title, x, 50);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.setTextColor(90);
  const lines = pdfHeaderLines(opts).flatMap(l => doc.splitTextToSize(l, pageWidth - left - 40) as string[]);
  lines.forEach((l, i) => doc.text(l, left, 68 + i * 12));
  doc.setTextColor(0);

  const columnStyles: Record<number, { halign: 'right' }> = {};
  (opts.rightAlign ?? []).forEach(i => { columnStyles[i] = { halign: 'right' }; });
  const body = rows.length ? rows : [[{ content: 'No rows', colSpan: Math.max(columns.length, 1) } as any]];

  autoTable(doc, {
    head: [columns],
    body,
    foot: opts.totals ? [opts.totals] : undefined,
    showHead: 'everyPage',
    showFoot: 'lastPage',
    startY: 68 + lines.length * 12 + 4,
    margin: { left, right: 40, bottom: 40, top: 40 },
    styles: { fontSize: 8, cellPadding: 4, overflow: 'linebreak' },
    headStyles: { fillColor: [8, 99, 67], textColor: 255 },
    footStyles: { fillColor: [232, 240, 236], textColor: 20, fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [245, 248, 246] },
    columnStyles,
  });

  const pages = doc.getNumberOfPages();
  for (let i = 1; i <= pages; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(120);
    doc.text(`${orgName()} · ${title}`, left, pageHeight - 20);
    doc.text(`Page ${i} of ${pages}`, pageWidth - 40, pageHeight - 20, { align: 'right' });
  }
  doc.setTextColor(0);
  doc.save(`${filename}_${todayYmd()}.pdf`);
}
